import { computeReturns } from './returns.js'
import { garchForecast } from './garch.js'
import { simulate, computeProbabilities } from './monteCarlo.js'
import { historicalVaR, sharpeRatio, maxDrawdown } from './risk.js'
import { computeAll, deriveSignals } from './indicators.js'

export const DISCLAIMER =
  'This forecast is generated by statistical models (Monte Carlo + GARCH). ' +
  'It represents probability ranges — NOT guaranteed predictions. ' +
  'Past patterns do not ensure future results. ' +
  'For educational and informational purposes only. ' +
  'Not financial advice. Consult a qualified adviser before investing.'

export async function generateForecast(bars, asset, horizonDays) {
  if (bars.length < 30) throw new Error(`Need at least 30 bars — only ${bars.length} available`)

  const prices = bars.map(b => b.adjClose ?? b.close)
  const stats = computeReturns(prices)
  const garchVol = garchForecast(stats.logReturns, horizonDays)
  const vol = garchVol ?? stats.annVol

  const startPrice = prices[prices.length - 1]
  const { paths, bands } = simulate({
    startPrice,
    drift: stats.annDrift,
    volatility: vol,
    days: horizonDays,
    simulations: 2000,
  })

  const probabilities = computeProbabilities(paths, startPrice, [0.05, 0.10, 0.20, -0.05, -0.10, -0.20])
  const indicators = computeAll(prices)
  const signals = deriveSignals(prices, indicators)

  const var95 = historicalVaR(stats.logReturns, 0.95)
  const sharpe = sharpeRatio(stats.logReturns)
  const dd = maxDrawdown(prices)

  const confidence = computeConfidence(bars.length, horizonDays, vol)

  return {
    asset,
    generatedAt: Date.now(),
    horizonDays,
    startPrice,
    bands,
    probabilities,
    signals,
    indicators,
    risk: { var95, sharpe, maxDrawdown: dd },
    annVol: vol,
    confidence,
    disclaimer: DISCLAIMER,
  }
}

function computeConfidence(dataCount, horizon, vol) {
  let c = 1.0
  if (dataCount < 252) c *= dataCount / 252
  c *= Math.max(0, 1 - horizon / 365)
  if (vol > 0.8) c *= 0.8 / vol
  return Math.min(Math.max(c, 0.05), 0.85)
}
